 async function saveBulkCompatibility(){
  if(!canWrite||!bulkPartIds.length||!bulkEquipmentIds.length)return;
  const quantity=Number(bulkQuantity);
  if(!Number.isFinite(quantity)||quantity<=0){alert(lang==="ar"?"أدخل كمية صحيحة لكل معدة":lang==="en"?"Enter a valid quantity per equipment":"Saisissez une quantité valide par équipement");return;}
  setBulkSaving(true);
  try{
   const targets=visibleEquipment.filter((e:any)=>bulkEquipmentIds.includes(e.id));
   if(!targets.length)throw new Error(lang==="ar"?"لم يتم اختيار معدات متاحة":lang==="en"?"No accessible equipment selected":"Aucun équipement accessible sélectionné");
   const tags=targets.map((e:any)=>e.equipment_tag).filter(Boolean);
   const {data:existing,error:existingError}=await supabase!.from("spare_part_equipment_compatibility").select("product_id,equipment_tag").eq("company_id",companyId).in("product_id",bulkPartIds).in("equipment_tag",tags);
   if(existingError)throw existingError;
   const existingKeys=new Set((existing||[]).map((x:any)=>x.product_id+"::"+x.equipment_tag));
   const rows:any[]=[];
   for(const equipment of targets){
    for(const productId of bulkPartIds){
     if(existingKeys.has(productId+"::"+equipment.equipment_tag))continue;
     rows.push({company_id:companyId,product_id:productId,equipment_tag:equipment.equipment_tag,equipment_name:equipment.name,equipment_model:equipment.model||null,manufacturer:equipment.manufacturer||null,quantity_per_equipment:quantity,is_critical:bulkCritical});
    }
   }
   if(rows.length){
    const {error}=await supabase!.from("spare_part_equipment_compatibility").insert(rows);
    if(error)throw error;
   }
   const skipped=bulkPartIds.length*targets.length-rows.length;
   setShowBulkCompatibility(false);setBulkPartIds([]);setBulkEquipmentIds([]);setBulkQuantity("1");setBulkCritical(false);setBulkSearch("");setBulkEquipmentSearch("");
   await load();await onSaved();
   alert(lang==="ar"?("تم ربط "+rows.length+" علاقة توافقية"+(skipped?"، وتم تجاوز "+skipped+" علاقة موجودة مسبقاً":"")):lang==="en"?("Created "+rows.length+" compatibility links"+(skipped?"; skipped "+skipped+" existing links":"")):("Association terminée : "+rows.length+" lien(s) créé(s)"+(skipped?" ; "+skipped+" lien(s) déjà existant(s) ignoré(s)":"")));
  }catch(error:any){alert(error?.message||"Erreur lors de l'association");}
  finally{setBulkSaving(false);}
 }

