   <label>Criticité<select value={form.criticality||"medium"} onChange={e=>setForm({...form,criticality:e.target.value})}><option value="low">Faible</option><option value="medium">Moyenne</option><option value="high">Haute</option><option value="critical">Critique</option></select></label>
